MATCH (u:User)-[w:WATCHED]->(m:Movie)-[:HAS]->(g:Genre)
WHERE u.email IS NOT NULL AND m.movieId > 100 AND m.movieId < 200 AND g.name IN ['Action', 'Comedy', 'Drama'] AND u.userId IN (
  WITH ip IN (u-[:USES]->ip WHERE ip.address CONTAINS '40.71')
  SELECT userId FROM ip
)
RETURN u.email;
